mapper.sql:
SELECT c.student_id, c.theme_id, c.theme_week_start, d.theme_version_id, max(c.completed_at) AS awarded_at FROM ( SELECT a.student_id, a.theme_id, a.theme_week_start, a.mission_id, min(a.completed_at) AS completed_at FROM attempt a WHERE a.context IN ('THEME_DAY', 'THEME_REVIEW') AND a.completed_at IS NOT NULL
AND a.student_id = #{round.studentId} AND a.theme_id = #{round.themeId} AND a.theme_week_start = #{round.weekStart}
GROUP BY a.student_id, a.theme_id, a.theme_week_start, a.mission_id ) c JOIN weekly_theme t ON t.id = c.theme_id JOIN weekly_theme_day d ON d.theme_version_id = COALESCE(t.published_version_id, t.current_version_id) AND d.mission_id = c.mission_id GROUP BY c.student_id, c.theme_id, c.theme_week_start, d.theme_version_id HAVING count(*) = 5

mapper.select:
SELECT id, student_id, theme_id, theme_week_start, theme_version_id, awarded_at, seen_at
FROM theme_frame
WHERE student_id = #{studentId} AND theme_id = #{key.themeId} AND theme_week_start = #{key.weekStart}
  AND theme_week_start < #{before}

SELECT f.theme_id, f.theme_week_start, v.title, v.intro_image_uri, f.awarded_at, f.seen_at
FROM theme_frame f
JOIN weekly_theme_version v ON v.id = f.theme_version_id
WHERE f.student_id = #{studentId} AND f.theme_week_start < #{before}
ORDER BY f.theme_week_start DESC, f.awarded_at DESC, f.id
LIMIT #{size} OFFSET #{offset}
